// 출제 범위를 바탕으로 직접 작성한 보충 연습문항.
// 배정 회차의 실제 출제 사실이나 공식 원문 복원을 뜻하지 않는다.
const rows=[];
const q=(round,subject,topic,text,options,explanation,given='')=>rows.push({round,subject,topic,text,options,answer:0,explanation,given});

// 40회 보충: 기본 개념과 R·통계·평가의 연결.
q(40,1,'데이터의 의미','상품의 색상과 판매 수량을 함께 기록했다. 정성·정량의 구분으로 적절한 것은?', ['색상은 정성적, 수량은 정량적','색상과 수량은 모두 정량적','숫자 코드로 저장하면 색상도 수량 척도이다','테이블로 저장하면 모두 정성적'], '색상은 성질·범주를 나타내고 수량은 양을 나타낸다. 숫자 코드와 저장 구조만으로 관측값의 의미가 바뀌지는 않는다.');
q(40,1,'데이터 마트','영업 부서가 매출 분석에 필요한 자료만 주제별로 관리한다. 가장 가까운 개념은?', ['데이터 마트','트랜잭션 로그의 원자성','개별 사용자의 암묵지','모형의 잔차'], '데이터 마트는 특정 부서·업무 주제의 분석 자료에 초점을 둔다. 기업 전체를 통합하는 DW와 범위의 차이를 보되 구현 방식은 조직에 따라 다를 수 있다.');
q(40,1,'데이터 가치','자료 수집 비용이 동일한 두 데이터셋의 활용 가치를 반드시 같다고 할 수 없는 이유는?', ['활용 목적·품질·결합 맥락에 따라 가치가 달라지기 때문','데이터 가치는 저장 바이트 수로만 결정되기 때문','비용과 가치가 언제나 같은 금액이기 때문','분석 기술은 활용 가치에 영향을 주지 않기 때문'], '생산 비용과 활용 가치는 다르다. 같은 자료도 다른 목적이나 다른 데이터와의 결합, 새 분석 기술에 따라 가치가 달라질 수 있다.');
q(40,1,'책임과 예측','미래의 행동 예측 점수만으로 실제 행위의 책임을 확정하려 한다. 가장 직접적인 위험은?', ['책임 원칙의 훼손','데이터 저장 용량 부족','표의 행·열 교환','분산의 단위 오류'], '예측은 실제 행위의 사실 확인과 동일하지 않다. 예측 결과만으로 책임을 확정하는 것은 책임 원칙 훼손의 위험과 연결된다.');
q(40,2,'기획의 목표','분석 착수 전에 성공 여부를 확인할 기준으로 가장 구체적인 것은?', ['다음 분기 동일 업무량의 평균 처리 시간을 10% 줄인다','최대한 좋은 분석을 한다','가능한 많은 그래프를 만든다','최신 기법을 사용하면 성공으로 본다'], '대상·기간·측정 지표·목표 수준이 있는 기준이 구체적이다. 도구나 그래프의 수는 업무 성과와 직접 같은 의미가 아니다.');
q(40,2,'과제 정의','고객 이탈 예측 과제를 정의할 때 함께 정해야 할 항목은?', ['이탈의 정의·예측 기준 시점·목표 기간','모형의 이름만','최종 보고서의 표지 색만','전체 고객 수만'], '누구를 언제 관찰해 어느 기간의 결과를 예측하는지 정해야 목표값과 입력 정보를 구성할 수 있다. 시점 정의는 미래 정보의 누수도 막는다.');
q(40,2,'프로젝트 위험','아직 발생하지 않았지만 데이터 승인 지연 가능성이 크다. 적절한 관리 방법은?', ['가능성·영향·대응책·담당자를 위험 목록에 기록','발생 전에는 계획에서 모두 제외','자료가 도착할 때까지 성공 기준을 없앰','지연 가능성을 최종 성능 지표로 사용'], '위험은 앞으로 발생할 수 있는 사건이다. 발생 가능성과 영향을 평가하고 담당자·징후·대안을 정해 관리한다.');
q(40,2,'거버넌스 책임','매출 정의를 변경할 때 승인 주체와 변경 이력 절차를 정하는 것은?', ['데이터 거버넌스의 책임·절차 관리','표본평균의 표준화','예측값의 임계값 계산','개별 그래프의 축 제거'], '거버넌스는 기준·책임·프로세스를 포함한다. 용어와 지표의 변경을 누가 승인하고 어떻게 반영하는지 정해야 조직의 일관성이 유지된다.');
q(40,3,'R 강제 변환','R에서 c(8, "9")의 일반적인 자료형은?', ['character','numeric','logical','data.frame'], '원자 벡터는 공통 자료형으로 값을 표현한다. 숫자와 문자열을 함께 넣으면 이 예에서는 모두 문자로 변환된다.');
q(40,3,'R 원소 선택','x=c(4,8,12,16)이다. x[c(1,3)]의 결과는?', ['4, 12','8, 16','1, 3','4, 8, 12'], 'R의 양수 인덱스는 1부터 시작하는 위치 선택이다. 첫 번째와 세 번째 값인 4와 12를 반환한다.');
q(40,3,'표본분산','값 2,4,6의 표본분산 s²는?', ['4','8/3','2','8'], '평균은 4, 편차 제곱합은 4+0+4=8이다. 불편 표본분산의 분모 n−1=2로 나누면 4가 된다.');
q(40,3,'중앙값','정렬된 값 1,3,7,9의 중앙값은?', ['5','4','7','3'], '관측 수가 짝수이므로 가운데 두 값 3과 7의 평균인 5를 사용한다. 극단값 1과 9의 평균을 쓰는 규칙은 아니다.');
q(40,3,'확률의 합','독립 사건 A·B의 확률이 각각 0.3·0.4이다. 적어도 하나가 일어날 확률은?', ['0.58','0.70','0.12','0.42'], '독립이므로 교집합은 0.3×0.4=0.12이다. 합집합은 0.3+0.4−0.12=0.58로 겹치는 부분을 한 번 뺀다.');
q(40,3,'검정의 결정','유의수준 0.05에서 p값 0.08인 검정의 적절한 결론은?', ['귀무가설을 기각하지 못한다','귀무가설이 참일 확률은 92%이다','대립가설이 확실히 거짓이다','귀무가설과 대립가설이 동시에 참이다'], 'p값이 유의수준보다 크므로 기각하지 못한다. 이는 귀무가설의 참을 증명하거나 그 확률을 계산한 결과가 아니다.');
q(40,3,'정밀도 계산','TP=18, FP=6, FN=9, TN=67일 때 정밀도는?', ['75%','66.7%','85%','18%'], '정밀도는 양성 예측 중 실제 양성으로 TP/(TP+FP)=18/24=75%다. 18/27은 재현율의 계산이다.');
q(40,3,'재현율 계산','TP=21, FN=7, FP=3, TN=69이다. 실제 양성을 찾아낸 비율은?', ['75%','87.5%','90%','21%'], '재현율은 실제 양성을 분모로 하므로 21/(21+7)=75%다. 정밀도의 분모에는 FN 대신 FP를 넣는다.');
q(40,3,'회귀 예측','예측식 ŷ=5+3x에서 x=4일 때 예측값은?', ['17','12','20','8'], '절편 5에 기울기 3×4=12를 더해 17을 얻는다. 이 식이 관측 범위와 업무 조건에 적절한지도 확인해야 한다.');
q(40,3,'거리 계산','점 (0,1)과 (3,5)의 유클리드 거리는?', ['5','7','25','4'], '좌표 차이는 3과 4다. 유클리드 거리는 √(3²+4²)=5이며 맨해튼 거리 7이나 제곱거리 25와 구분한다.');
q(40,3,'교차 검증','4겹 교차 검증에서 각 반복의 검증 자료를 바꾸는 목적은?', ['자료 분할에 따른 성능 변동을 함께 평가','평가 자료의 정답을 학습 입력으로 사용','모든 자료를 동시에 학습·검증에 중복 사용','모형 선택이 끝난 뒤 학습을 금지'], '서로 다른 검증 구간의 결과를 종합해 분할에 따른 변동을 확인하고 자료를 효율적으로 활용한다. 각 반복에서 검증 구간은 그 반복의 학습에 사용하지 않는다.');
q(40,3,'지지도 계산','120건의 거래에서 A와 B 동시 거래가 24건이다. A→B 지지도는?', ['20%','24%','40%','80%'], '지지도는 전체 거래 중 동시 출현 비율이다. 24/120=0.2이며 선행 항목 구매 건수로 나누는 신뢰도와 다르다.');

// 41회 보충.
q(41,1,'SECI 연결화','서로 다른 두 문서의 지식을 결합해 새 매뉴얼을 만들었다. 지식 전환은?', ['형식지→형식지의 연결화','암묵지→형식지의 표출화','형식지→암묵지의 내면화','암묵지→암묵지의 공통화'], '문서로 표현된 지식을 또 다른 명시적 지식으로 결합하므로 연결화다. 몸으로 체득한 경험을 문서화하는 표출화와 다르다.');
q(41,1,'반정형 데이터','고객 기록이 JSON의 키·값으로 저장되어 있다. 구분으로 적절한 것은?', ['구조 정보가 함께 있는 반정형 데이터','구조 표현이 전혀 없는 비정형 데이터만 가능','모든 키가 숫자이므로 정량 데이터만 가능','관계형 DB와 반드시 같은 고정 구조'], 'JSON은 키 등으로 구조를 표현하는 반정형의 대표 사례다. 고정 테이블 여부와 정성·정량의 의미 구분은 별개이다.');
q(41,1,'OLAP 드릴다운','연간 매출에서 분기별·월별 매출로 더 자세히 내려가는 동작은?', ['드릴다운','롤업','트랜잭션 롤백','자료형 강제 변환'], '드릴다운은 상세 수준으로 내려가는 분석이다. 월별 자료를 연간 수준으로 모으는 롤업과 방향이 반대다.');
q(41,1,'데이터 정확성','주소 필드가 모든 행에 있지만 실제 주소와 다르다. 가장 직접적으로 부족한 품질은?', ['정확성','완전성만','처리 속도만','파일 압축률'], '값이 존재하는 완전성과 실제 사실에 맞는 정확성은 다르다. 누락이 없어도 값이 잘못되면 정확성 문제가 있다.');
q(41,2,'대상과 방법','분석 대상과 방법을 모두 알고 있을 때의 기획 유형은?', ['최적화','발견','통찰','솔루션'], '두 축이 모두 알려졌으면 최적화 유형이다. 대상만 알면 솔루션, 방법만 알면 통찰, 둘 다 모르면 발견으로 구분한다.');
q(41,2,'하향식 문제 정의','매출 감소라는 업무 문제를 분석 질문으로 구체화한 문장은?', ['어떤 고객군의 재구매율이 최근 3개월에 얼마나 줄었는가','우선 임의의 군집 수를 7로 고정한다','모형의 정확도만 높이면 원인이 확인된다','분석 결과를 보고 나중에 목표를 정한다'], '업무 문제를 대상·기간·지표가 있는 분석 질문으로 바꾸는 것이 문제 정의다. 기법을 먼저 고정하거나 성공 기준을 뒤늦게 정하지 않는다.');
q(41,2,'KDD 순서','데이터 정제 후 분석에 맞게 변수를 변환하는 KDD 단계는?', ['변환','해석·평가','선택','데이터 마이닝 자체'], 'KDD의 선택→전처리→변환→마이닝→해석·평가 중 표현과 차원을 분석 목적에 맞추는 단계가 변환이다. 마이닝은 패턴을 찾는 별도 단계다.');
q(41,2,'전사 로드맵','추천 모형보다 공통 고객번호 통합을 먼저 진행하는 이유로 적절한 것은?', ['추천 분석이 통합 고객 자료를 필요로 하는 선행 관계','공통 데이터는 업무 효과와 관계가 없기 때문','어려운 과제는 항상 영구 제외해야 하기 때문','우선순위에는 의존성을 고려할 수 없기 때문'], '기반 과제가 여러 후속 과제의 실행을 가능하게 할 수 있다. 기대 효과만이 아니라 의존성·자원·일정을 함께 고려한다.');
q(41,3,'R 제외 인덱스','x=c(2,5,9,11)에서 x[-2]의 결과는?', ['2, 9, 11','5','−2','2, 5'], '음수 인덱스는 해당 위치를 제외한다. 두 번째 값 5를 제외하고 나머지 원소를 반환한다.');
q(41,3,'행렬 채움','R의 matrix(1:6,nrow=2)를 기본 설정으로 만들면 첫 번째 열은?', ['1, 2','1, 4','1, 3, 5','2, 4, 6'], 'R matrix는 기본적으로 열을 먼저 채운다. 2행이므로 첫 열 1·2, 다음 열 3·4, 마지막 열 5·6이 된다.');
q(41,3,'결측 판별','R에서 결측값 x를 검사할 때 적절한 함수는?', ['is.na(x)','x == NA','x == NULL','mean(x)가 항상 0인지 검사'], 'NA와의 일반 비교는 결측 결과를 반환할 수 있으므로 is.na를 사용한다. NULL과 NA는 서로 다른 개념이다.');
q(41,3,'표준오차','모표준편차 12, 독립 표본 수 36일 때 표본평균의 표준오차는?', ['2','12','6','1/3'], '평균의 표준오차는 σ/√n=12/6=2다. 개별 관측의 산포 12와 평균 추정의 흔들림 2는 다르다.');
q(41,3,'분포의 단위','가격을 원에서 천 원으로 바꾸었다. 표준편차의 변화는?', ['원래 값의 1/1000','원래 값의 1/1000000','그대로','반드시 0'], '표준편차는 원래 자료와 같은 단위라 상수의 절댓값에 비례한다. 분산은 그 상수의 제곱에 비례한다.');
q(41,3,'이항 기대값','독립 20회 시행의 성공 확률이 매번 0.3이다. 성공 횟수의 기대값은?', ['6','0.3','4.2','14'], '이항분포의 기대값은 np=20×0.3=6이다. 분산 np(1−p)=4.2와 구분한다.');
q(41,3,'오류의 조건','귀무가설이 실제로 참인데 기각했다. 해당 오류는?', ['제1종 오류','제2종 오류','검정력','추정량의 불편성'], '제1종 오류는 참인 귀무가설을 기각한 경우다. 거짓인 귀무가설을 기각하지 못하면 제2종 오류이다.');
q(41,3,'ANOVA 해석','세 집단의 평균 동일성을 ANOVA로 기각했다. 적절한 해석은?', ['적어도 하나의 평균 차이에 대한 근거가 있다','모든 집단 쌍의 평균이 다르다','모든 집단의 분산이 다르다고 입증했다','모든 관측값이 서로 다르다'], '전체 평균 동일성의 기각은 적어도 하나의 차이를 뜻한다. 어느 집단 쌍이 다른지는 사후 비교가 필요하고 분산 동일성 검정과도 다르다.');
q(41,3,'MSE 계산','두 건의 실제값−예측값이 2와 −4다. MSE는?', ['10','3','6','√10'], '제곱오차는 4와 16이고 평균은 10이다. MAE는 (2+4)/2=3, RMSE는 √10이다.');
q(41,3,'의사결정나무','나무의 잎 노드가 학습 자료에서 모두 순수하다. 반드시 말할 수 있는 것은?', ['새 자료의 성능은 별도로 확인해야 한다','최종 평가 정확도도 반드시 100%이다','과적합 가능성이 완전히 없어진다','다른 모형보다 항상 우수하다'], '세밀한 분할은 학습 자료에 과적합할 수 있다. 학습의 순도와 새 자료의 일반화 성능은 다르다.');
q(41,3,'PCA 비율','공분산 행렬의 고유값이 5,3,2다. 첫 두 성분의 누적 설명분산 비율은?', ['80%','50%','60%','20%'], '전체 고유값 합은 10, 첫 두 합은 8이다. 누적 설명분산은 8/10=80%이며 성분 개수의 비율과 다르다.');
q(41,3,'연관 향상도','신뢰도 P(B|A)=0.6, P(B)=0.4다. A→B 향상도는?', ['1.5','0.24','0.2','0.67'], '향상도는 0.6/0.4=1.5다. 1보다 크므로 B의 기본 비율보다 A 조건 아래 B가 더 흔한 연관을 나타내며 인과 효과를 뜻하지 않는다.');

// 42회 보충.
q(42,1,'내면화','신입이 매뉴얼을 반복 실습해 작업 요령을 몸에 익혔다. SECI에서 해당 전환은?', ['형식지→암묵지의 내면화','암묵지→형식지의 표출화','형식지→형식지의 연결화','암묵지→암묵지의 공통화만'], '문서로 표현된 지식을 실습해 개인의 숙련으로 체득하는 형식→암묵 전환이다. 문서를 작성하는 표출화와 방향이 반대다.');
q(42,1,'물리적 독립성','저장 파일 배치와 인덱스를 바꿔도 사용자의 논리적 조회 구조가 유지된다. 관련 성질은?', ['물리적 데이터 독립성','데이터의 무작위성','표본의 독립 추출','모형의 편향 제거'], '물리적 저장·접근 구조의 변경이 논리 구조와 응용에 미치는 영향을 줄이는 것이 물리적 독립성이다. 모든 변경이 무영향이라는 절대적 보장은 아니다.');
q(42,1,'SCM','원재료 공급부터 생산·재고·배송의 흐름을 연결해 관리하는 대표 시스템은?', ['SCM','CRM','SECI','OLS'], 'SCM은 공급망 관리다. CRM은 고객 관계와 접점 관점이며 SECI는 지식 전환, OLS는 회귀 추정 방식이다.');
q(42,1,'메타데이터','컬럼의 단위·업무 정의·갱신 주기를 설명하는 정보는?', ['메타데이터','오직 실제 매출 관측값','회귀의 잔차','분류의 목표값만'], '메타데이터는 값의 의미·구조·관리 상태를 설명한다. 실제 관측값과 구분해야 데이터의 단위와 기준 시점을 올바르게 해석할 수 있다.');
q(42,2,'상향식 출발','고객 로그를 탐색하다 예상하지 못한 사용 패턴을 발견해 과제를 제안했다. 가까운 접근은?', ['상향식 과제 발굴','정의된 업무 문제만으로 시작하는 하향식','최종 배포 뒤 모든 평가를 생략하는 방식','기술과 업무를 분리해 소통하지 않는 방식'], '데이터의 탐색·발견에서 업무 기회를 찾는 상향식 접근이다. 발견한 패턴을 검증하고 업무 가치와 연결해야 한다.');
q(42,2,'CRISP 업무 평가','모형 점수가 좋지만 현업의 비용 절감 기준을 충족하지 못했다. 핵심 검토 단계는?', ['평가','단순 파일 압축','데이터 이해만으로 모든 단계 종료','원자료 삭제'], 'CRISP-DM 평가는 분석 결과가 업무 목표를 충족하는지 확인한다. 모형의 기술 지표가 높다고 비즈니스 평가를 생략할 수 없다.');
q(42,2,'범위 변경','종료 직전에 신규 분석 기능을 요구받았다. 적절한 대응은?', ['가치·작업량·일정·비용·품질 영향을 검토해 승인된 변경을 반영','기존 완료 기준을 알리지 않고 삭제','모든 요구를 무조건 즉시 추가','변경은 문서에 남기지 않는다'], '변경은 범위와 일정·자원에 영향을 줄 수 있다. 합의된 절차로 영향을 평가하고 승인된 계획을 갱신해야 한다.');
q(42,2,'준비도 진단','데이터·인력·기법·업무·문화·인프라의 확보 상태를 보는 진단은?', ['분석 준비도','표본 추출률','모형의 R²','군집의 실루엣'], '준비도는 분석 수행에 필요한 여러 영역의 상태를 진단한다. 도입·활용·확산·최적화의 발전 단계인 성숙도와 구분한다.');
q(42,3,'R 재활용','R에서 c(1,2,3,4)+c(10,20)의 결과는?', ['11,22,13,24','11,22','11,12,13,14','21,22,23,24'], '짧은 벡터 10·20이 10·20·10·20으로 재활용되어 원소별로 더해진다. 긴 길이가 짧은 길이의 배수인 예이다.');
q(42,3,'R 리스트 추출','리스트 L의 첫 구성요소 자체를 꺼내는 표현은?', ['L[[1]]','L[1]만이 구성요소 자체를 반환','L(1)','L{1}'], '[[는 단일 구성요소를 추출하고 [는 리스트의 부분 리스트를 반환한다. 반환 구조의 차이를 확인해야 한다.');
q(42,3,'IQR 경계','Q1=10, Q3=18이다. 상단의 1.5IQR 이상치 후보 경계는?', ['30','26','18','22'], 'IQR=8, 상단 경계=18+1.5×8=30이다. 경계 밖의 관측은 후보이며 오류 여부를 확인하지 않고 자동 삭제하지 않는다.');
q(42,3,'왜도 판별','큰 값 방향의 꼬리가 긴 분포의 전형적인 왜도 부호는?', ['양수','음수','반드시 0','자료 수가 짝수이면 음수'], '왜도 부호는 꼬리 방향을 기준으로 읽는다. 큰 값 쪽 긴 꼬리는 양의 왜도이며 표본 수의 홀짝과 관계없다.');
q(42,3,'포아송 분포','구간당 평균 발생 횟수가 λ인 포아송분포의 평균·분산은?', ['둘 다 λ','평균 λ, 분산 λ²','평균 0, 분산 1','둘 다 표본 크기 n'], '포아송분포는 발생 횟수의 모형이고 평균과 분산이 모두 λ다. 실제 자료에서 과산포 등이 있으면 가정의 적합성을 검토한다.');
q(42,3,'신뢰구간','같은 방법으로 표본을 반복 추출해 95% 신뢰구간을 만든다. 올바른 해석은?', ['그 절차로 만든 구간의 약 95%가 고정된 모수를 포함한다','계산한 모수가 구간 안에서 95% 확률로 이동한다','표본의 95% 관측값이 반드시 구간에 있다','모집단의 95% 값이 평균 구간에 포함된다'], '빈도주의 신뢰수준은 반복 절차의 포함률이다. 평균의 신뢰구간을 개별 관측의 95% 범위와 혼동하지 않는다.');
q(42,3,'대응 검정','같은 사람 20명의 교육 전후 점수를 비교한다. 분석 구조는?', ['대응 표본의 차이를 이용한 비교','서로 독립인 두 표본만의 비교','두 변수의 빈도 독립성만 검정','모든 점수를 새 독립 고객으로 취급'], '같은 사람의 전후 관측은 짝이 있는 자료다. 대응 차이에 대한 가정과 검정 방법을 확인해야 한다.');
q(42,3,'다중공선성','설명변수끼리 강한 선형 관계가 있을 때 생길 수 있는 문제는?', ['개별 회귀계수의 불확실성과 불안정성 증가','모든 설명변수의 분산이 반드시 0','예측값이 무조건 이진값으로 변함','R²가 반드시 음수가 됨'], '다중공선성은 계수 추정 분산을 키우고 해석을 불안정하게 할 수 있다. 전체 예측이 좋아도 개별 계수는 불확실할 수 있다.');
q(42,3,'차분','시계열 값이 3,7,12,18이다. 1차 차분은?', ['4,5,6','3,4,5,6','7,12,18','10,19,30'], '연속된 값의 차이를 계산한다. 7−3=4, 12−7=5, 18−12=6으로 길이가 하나 줄어든다.');
q(42,3,'지니 계산','이진 클래스 비율이 0.8과 0.2인 노드의 지니 불순도는?', ['0.32','0.68','0.16','0.80'], '1−(0.8²+0.2²)=1−0.68=0.32다. 하나의 클래스만 있는 노드에서는 0이다.');
q(42,3,'KNN 척도','KNN에서 소득의 큰 단위가 거리 계산을 지배한다. 적절한 점검은?', ['변수 척도·표준화와 거리 정의','정답을 입력 변수에 추가','K를 항상 1로 고정','모든 작은 값의 변수를 삭제'], '거리 모형은 단위의 영향을 받을 수 있다. 학습 구간에서 척도를 맞추고 검증으로 거리·K 등의 선택을 평가한다.');
q(42,3,'군집 중심','K-means 군집의 1차원 값이 2,5,8이다. 갱신 중심은?', ['5','2','8','중앙값이므로 모든 자료에서 평균과 다름'], 'K-means는 군집에 배정된 값들의 평균으로 중심을 갱신한다. 이 예는 (2+5+8)/3=5이고 평균과 중앙값이 우연히 같다.');

// 43회 보충.
q(43,1,'DIKW 행동','데이터 분석으로 얻은 지식을 활용해 다음 달의 발주 전략을 결정했다. DIKW 단계는?', ['지혜','원시 데이터','단순 정보만','값의 자료형'], '관계와 규칙의 이해를 바탕으로 상황에 맞는 행동을 판단하는 지혜 단계다. 단순 관측이나 비교와 구분한다.');
q(43,1,'DW 비휘발성','DW의 비휘발성에 대한 적절한 설명은?', ['분석용 자료를 적재해 보존하며 일상 거래처럼 빈번한 수정 중심이 아니다','한 번 저장하면 어떤 유지보수도 영원히 불가능하다','자료는 접속을 끊으면 모두 사라진다','현재 거래만 저장하고 과거 이력을 삭제한다'], '비휘발성은 분석을 위해 보존된 자료를 일상 거래처럼 계속 갱신하지 않는 특성이다. 오류 수정이나 관리 작업이 불가능하다는 의미는 아니다.');
q(43,1,'데이터 시의성','정확한 매출 자료가 의사결정 마감 뒤에 도착한다. 부족한 품질 관점은?', ['적시성','정확성만','속성의 숫자형 여부','최빈값'], '필요한 시점에 사용할 수 있는지가 적시성이다. 값이 정확해도 너무 늦게 도착하면 업무 활용에 제한이 생긴다.');
q(43,1,'분석의 인과','온라인 행동 로그에서 X와 Y가 함께 증가했다. 적절한 결론은?', ['연관을 확인했으며 인과는 추가 검증이 필요하다','X가 Y의 원인임이 자동 입증된다','두 변수 사이의 교란은 불가능하다','시간 순서와 비교 설계는 불필요하다'], '관측된 상관만으로 인과를 확정할 수 없다. 숨은 요인·선택 편향·시간 순서와 비교 설계 등을 추가로 검토한다.');
q(43,2,'CRISP 데이터 준비','중복 제거·변수 구성·자료 결합·형식화를 통해 모델링 자료를 만드는 단계는?', ['데이터 준비','최종 전개만','업무 이해만','모형의 개별 계수 검정만'], 'CRISP-DM 데이터 준비는 분석에 쓸 최종 데이터셋을 만드는 작업이다. 처리 규칙을 기록해 결과를 재현할 수 있도록 한다.');
q(43,2,'분석 조직','전문 분석 인력을 한 부서에 모아 공통 표준과 역량을 공유하는 구조는?', ['중앙집중형','모든 부서가 서로 독립된 기능형만','표본 층화형','지도학습형'], '중앙집중형은 전문 역량·표준의 공유가 강점이다. 현업의 업무 이해와 소통을 유지하는 방안도 함께 필요하다.');
q(43,2,'시범 적용','두 점포에서 실제 발주 업무에 모형을 사용해 운영 효과를 확인했다. 가까운 검증은?', ['파일럿','단순 자료형 변환','공분산 계산만','개념 검증 이전의 무조건 전사 배포'], '제한된 실제 환경의 적용을 통해 사용 과정과 효과를 확인하는 파일럿이다. 기술 가능성만 검토하는 PoC보다 운영의 범위를 포함한다.');
q(43,2,'표준 관리','부서 A와 B가 같은 매출을 서로 다른 계산식으로 보고한다. 우선 점검할 것은?', ['공통 지표 정의·범위·책임과 변경 절차','그래프 색상만 동일하게 조정','모든 보고서를 단순 평균','한 부서 자료를 근거 없이 제거'], '정의·분모·기간·포함 범위를 합의해야 비교가 가능하다. 시각적 형식만 맞춰서는 지표의 의미 차이가 해결되지 않는다.');
q(43,3,'R 논리 선택','x=c(3,7,9)에서 x[x>5]는?', ['7, 9','FALSE, TRUE, TRUE','3','2, 3'], 'x>5는 FALSE·TRUE·TRUE의 논리 벡터다. 이를 인덱스로 사용하면 TRUE 위치의 실제 값인 7과 9를 선택한다.');
q(43,3,'R 행렬 연산','두 행렬의 같은 위치 원소끼리 곱하는 R 연산자는?', ['*','%*%','%in%','%%'], '*는 원소별 곱이며 %*%는 행렬곱이다. 행렬곱의 차원 조건과 원소별 연산을 구분해야 한다.');
q(43,3,'표본평균 분포','독립·동일분포이고 분산이 유한한 관측을 많이 모으면 표본평균의 표집분포는?', ['적절히 표준화했을 때 정규분포에 가까워진다','원자료 자체가 반드시 정규분포로 변한다','표본평균의 분산이 표본 수에 비례해 증가한다','항상 원자료와 같은 분포 모양이다'], '중심극한정리는 표본평균 등 합의 표집분포에 관한 것이다. 원자료의 분포를 정규분포로 바꾸는 변환이 아니다.');
q(43,3,'베르누이 분산','성공 확률 p=0.4인 베르누이 변수의 분산은?', ['0.24','0.4','0.16','0.6'], '분산은 p(1−p)=0.4×0.6=0.24다. 평균 p와 제곱 p²를 혼동하지 않는다.');
q(43,3,'검정력','제2종 오류 확률 β가 0.15일 때 검정력은?', ['0.85','0.15','0.05','1.15'], '검정력은 실제 대립 상황에서 귀무가설을 기각할 확률로 1−β=0.85다. 유의수준 α와 별개의 조건부 확률이다.');
q(43,3,'교차표 자유도','3행·4열 교차표의 카이제곱 독립성 검정 자유도는?', ['6','12','7','5'], '자유도는 (행 수−1)(열 수−1)=2×3=6이다. 총 칸 수 12와 다르며 기대빈도 등의 적용 조건도 확인한다.');
q(43,3,'공분산 단위','키(cm)와 몸무게(kg)의 공분산 단위는?', ['cm·kg','단위 없음','cm만','kg²'], '공분산은 두 편차의 곱을 이용하므로 두 단위의 곱이다. 이를 표준편차의 곱으로 나눈 상관계수는 단위가 없다.');
q(43,3,'회귀 잔차','실제값 23, 예측값 20일 때 잔차 y−ŷ는?', ['3','−3','43','9'], '잔차를 실제−예측으로 정의하면 23−20=3이다. 제곱오차 9와 잔차 자체를 구분한다.');
q(43,3,'시계열 정상성','약한 정상성에 대한 설명으로 적절한 것은?', ['공분산은 시점 위치보다 시차에 의존한다','모든 관측값이 똑같아야 한다','모든 시차의 상관이 0이어야 한다','평균이 일정 속도로 증가해야 한다'], '약정상은 일정한 평균·분산과 시차에 따른 공분산을 가정한다. 백색잡음이나 상수 시계열만을 뜻하지 않는다.');
q(43,3,'배깅','배깅의 대표 자료 생성 방식은?', ['원자료에서 복원 추출한 여러 학습 표본','모든 오답을 정답으로 교체','검증 자료를 모두 학습에 중복','자료 없이 나무의 깊이만 반복 변경'], '부트스트랩 복원 추출로 여러 모형을 학습하고 예측을 합친다. 중복 관측과 특정 표본에 포함되지 않은 관측이 생길 수 있다.');
q(43,3,'특이도','TN=72, FP=8이다. 특이도는?', ['90%','10%','80%','72%'], '특이도는 실제 음성 중 음성으로 맞힌 비율로 72/(72+8)=0.9다. 위양성률은 그 보완 비율인 0.1이다.');
q(43,3,'연관규칙 방향','A→B와 B→A의 지표에 대한 일반적인 관계는?', ['지지도·향상도는 같고 신뢰도는 다를 수 있다','신뢰도는 항상 같고 지지도는 항상 다르다','모든 지표가 반드시 다르다','향상도만 방향에 따라 항상 달라진다'], '지지도는 같은 교집합이고 향상도는 P(A∩B)/(P(A)P(B))이므로 대칭이다. 신뢰도는 선행 조건의 확률이 분모라 방향에 따라 달라질 수 있다.');

// 44회 보충.
q(44,1,'암묵지 공유','견습생이 숙련자와 함께 일하며 말로 표현되지 않은 요령을 배웠다. 전환은?', ['공통화','연결화','표출화','형식지의 단순 복사'], '함께 경험하며 암묵지를 암묵지로 공유하는 공통화다. 문서가 산출되거나 문서를 읽는 것과 구분한다.');
q(44,1,'빅데이터 다양성','표·음성·이미지·로그를 함께 활용할 때 가장 직접적으로 관련된 3V는?', ['Variety','Volume만','Velocity만','Value만'], '다양한 형식과 구조는 Variety다. 저장량은 Volume, 생성·처리 속도는 Velocity이며 실제 활용 가치는 추가 관점이다.');
q(44,1,'DB 공유와 무결성','공유 DB에서 존재하지 않는 고객번호를 주문에 입력하지 못하게 하는 것은?', ['참조 무결성 제약','단순 데이터 압축','평균 대체','무작위 자료 추출'], '주문의 외래키가 고객 테이블의 참조 키와 연결되는 조건을 관리하는 참조 무결성이다. 공유 데이터의 일관성을 유지하는 데 도움을 준다.');
q(44,1,'과거 자료의 가치','현재 재고값만 있고 과거 재고 이력이 없다. 직접 어려워지는 분석은?', ['지난 1년의 재고 추세 분석','현재 재고의 조회','현재 품목의 이름 확인','현재 단위의 확인'], '추세는 시간에 따른 관측의 변화가 필요하다. 현재 상태만으로 과거 시점별 재고의 경로를 복원할 수는 없다.');
q(44,2,'통찰 유형','분석 방법은 알려져 있지만 어느 업무 대상에서 새 가치를 찾을지 탐색 중이다. 유형은?', ['통찰','최적화','솔루션','발견'], '대상은 모르고 방법은 아는 유형이 통찰이다. 두 축의 알려짐을 먼저 정한 뒤 이름을 연결한다.');
q(44,2,'경제적 타당성','분석의 기대 편익과 총 구축·운영 비용을 비교하는 검토는?', ['경제적 타당성','잔차의 정규성','자료형의 동일성','지지도 기준만'], '경제성은 가치와 비용의 비교다. 데이터·인력·일정 등 실행 가능성도 중요하지만 각각 다른 검토 항목이다.');
q(44,2,'분석 결과 활용','예측 점수는 매일 나오지만 현업의 실행 담당자가 없다. 부족한 설계는?', ['결과 사용 주체와 업무 절차','모형 파일의 확장자','설명변수 이름의 알파벳 순서','저장된 그래프 수'], '결과가 행동으로 연결되어야 가치가 생긴다. 실행 담당자·시점·처리 용량·운영 책임과 효과 측정을 설계해야 한다.');
q(44,2,'성숙도 단계','일부 업무에 분석을 사용한 뒤 조직 전체의 여러 업무로 넓히는 단계에 가까운 것은?', ['확산','도입 이전','자료 삭제','단순 저장'], '성숙도는 도입→활용→확산→최적화의 발전을 본다. 사용 범위를 조직 전체로 넓히는 것은 확산 관점이다.');
q(44,3,'R 길이','R에서 length(c(2,4,NA,8))의 결과는?', ['4','3','NA','8'], 'length는 원소 수를 세므로 결측값도 한 원소로 포함한다. 결측을 제외한 관측 수를 계산하려면 별도 논리 조건을 사용한다.');
q(44,3,'R 평균 결측','R에서 mean(c(2,NA,6),na.rm=TRUE)의 결과는?', ['4','NA','8/3','0'], 'na.rm=TRUE는 결측을 제외해 2와 6의 평균을 계산한다. (2+6)/2=4이며 결측을 0으로 바꾼 것과 다르다.');
q(44,3,'척도 판별','섭씨 온도를 측정했다. 통상적인 척도 구분은?', ['등간 척도','명목 척도','서열 척도','절대 0을 가진 비율 척도'], '섭씨는 차이가 의미 있는 등간 척도다. 0℃가 열의 완전한 부재를 뜻하지 않으므로 20℃가 10℃의 두 배라는 비율 해석은 적절하지 않다.');
q(44,3,'정규 표준점수','평균 50, 표준편차 5인 정규변수에서 값 60의 z 점수는?', ['2','10','12','0.5'], 'z=(60−50)/5=2다. 평균보다 2표준편차 위라는 뜻이며 원래 값과 같은 단위를 갖지 않는다.');
q(44,3,'구간과 표본 수','다른 조건이 같고 평균 신뢰구간의 임계값이 같다면 표본 수를 16에서 64로 늘릴 때 표준오차는?', ['절반','4배','1/4','변하지 않음'], '표준오차는 √n에 반비례한다. 표본 수 4배는 표준오차 1/2이며 n에 직접 반비례하는 것이 아니다.');
q(44,3,'카이제곱 빈도','카이제곱 독립성 검정의 주된 입력으로 적절한 것은?', ['범주별 관측 빈도의 교차표','모든 관측의 시간 순서만','연속값의 단위 없는 순위만','개별 회귀계수의 기울기만'], '범주형 변수의 교차 빈도를 독립 가정의 기대빈도와 비교한다. 작은 기대빈도나 표본 설계 조건은 추가로 확인해야 한다.');
q(44,3,'상관 단위','키를 cm에서 m로 바꾸는 양의 단위 변환 후 Pearson 상관계수는?', ['변하지 않는다','1/100로 줄어든다','100배 커진다','반드시 0이 된다'], '공분산과 표준편차의 변화가 상관식에서 상쇄된다. 양의 선형 단위 변환은 Pearson r을 바꾸지 않는다.');
q(44,3,'등분산성 진단','예측값이 클수록 잔차의 산포가 넓어지는 깔때기 모양이다. 점검할 가정은?', ['등분산성','설명변수의 명목형 여부만','모든 값이 양수인지 여부만','클래스의 개수만'], '잔차 산포가 일정하지 않은 패턴은 이분산성의 단서다. 원인과 분석 목적을 확인하고 적절한 변환·모형·추론 방법을 검토한다.');
q(44,3,'ARIMA 차분','ARIMA(2,1,0)에서 숫자 1의 뜻은?', ['차분 횟수 d','MA 차수 q','설명변수 수','계절 주기 자체'], 'ARIMA(p,d,q)의 가운데 d가 차분 횟수다. 이 예의 AR 차수는 2, MA 차수는 0이다.');
q(44,3,'랜덤 포레스트','랜덤 포레스트에서 분할 후보 변수를 무작위로 일부 고르는 주요 목적은?', ['나무 사이의 상관을 낮추는 데 도움','모든 나무가 정확히 같은 구조가 되도록','반드시 모든 계수를 0으로 만들기','정답을 삭제해 지도학습을 비지도학습으로 바꾸기'], '부트스트랩과 변수 부분집합의 무작위성으로 나무의 다양성을 만든다. 상관이 낮은 모형을 결합하면 분산 감소의 이득을 얻기 쉽다.');
q(44,3,'DBSCAN 잡음','어느 핵심점의 밀도 연결 군집에도 속하지 않는 점을 DBSCAN은 어떻게 다룰 수 있는가?', ['잡음으로 구분','반드시 가장 가까운 중심에 배정','항상 새 단일 군집으로 확정','모든 점을 한 군집으로 병합'], 'DBSCAN은 밀집 구조에서 떨어진 점을 잡음으로 둘 수 있다. 모든 점을 지정한 K개의 중심에 배정하는 K-means와 다르다.');
q(44,3,'신뢰도 분모','150건 중 A가 50건, B가 60건, A·B가 30건이다. A→B 신뢰도는?', ['60%','20%','50%','40%'], '선행 조건 A의 50건을 분모로 하므로 30/50=60%다. 30/150은 지지도, 30/60은 역방향 신뢰도다.');

// 45회 보충.
q(45,1,'OLTP 목적','고객의 결제 승인과 재고 차감을 빠르고 정확하게 처리하는 작업에 가까운 것은?', ['OLTP','OLAP만','PCA','KDD 해석 단계만'], '짧고 빈번한 일상 거래는 OLTP의 대표 목적이다. 기간별 집계·다차원 분석을 주로 지원하는 OLAP와 구분한다.');
q(45,1,'DB 지속성','성공적으로 확정된 거래 결과가 장애 후에도 보존되는 ACID 성질은?', ['지속성','원자성만','격리성만','비율 척도'], '지속성은 확정된 결과의 보존이다. 원자성은 거래의 전체 성공·전체 취소, 격리성은 동시 거래의 간섭 관리와 관련된다.');
q(45,1,'데이터 사이언스 역량','분석 가정을 현업에 설명하고 서로 다른 이해관계를 조정하는 능력은?', ['소프트 스킬','자료 압축 알고리즘만','회귀계수 계산만','서버 메모리 증설'], '소통·협력·업무 이해는 소프트 스킬이다. 프로그래밍·통계·데이터 처리 등의 하드 스킬과 함께 분석 활용에 필요하다.');
q(45,1,'데이터 결합','판매 이력에 날씨를 연결해 발주량을 개선했다. 데이터 가치의 핵심은?', ['새 맥락의 결합과 실제 업무 적용','파일 수가 늘었으므로 가치는 언제나 두 배','모든 개인정보를 공개한 것','관측값이 많으면 검증이 불필요해진 것'], '자료 결합으로 새로운 설명 맥락을 얻고 발주 개선으로 비용·성과를 바꿨다. 자료량 증가 자체가 정해진 비율의 가치를 보장하지는 않는다.');
q(45,2,'발견 유형','분석 대상과 적용 방법을 모두 탐색해야 하는 기획 유형은?', ['발견','최적화','통찰','솔루션'], '대상과 방법 둘 다 미지이면 발견이다. 대상만 알려져 있으면 솔루션, 방법만 알려져 있으면 통찰이다.');
q(45,2,'PoC 목적','큰 구축 투자 전에 이 데이터로 목표 예측이 가능한지 작게 시험했다. 목적은?', ['핵심 분석 가능성의 개념 검증','최종 운영 책임의 영구 제거','모든 현장에 즉시 적용','사업 지표 대신 코드 줄 수만 확인'], 'PoC는 핵심 가정·기술 가능성을 검증하는 성격이다. 성공 기준과 이후 확대 조건을 정하고 대표성과 운영 제약도 확인한다.');
q(45,2,'KPI 정의','처리 시간 15% 절감을 평가하기 전에 정해야 할 것은?', ['업무 단위·분모·기간·품질 기준','최종 그림의 파일명만','검증이 끝난 뒤 임의 기준선','모형의 복잡도가 높을수록 자동 성공'], '동일한 업무량과 품질에서 어떤 시간 지표를 비교할지 정의해야 한다. 기준 기간·분모가 다르면 효과를 잘못 해석할 수 있다.');
q(45,2,'문화와 역량','분석 도구는 충분하지만 현업이 결과를 이해하거나 활용하지 못한다. 우선 보완할 영역은?', ['교육·소통·활용 절차와 문화','그래픽 처리 장치만 추가 구매','모든 분석 과제의 범위 삭제','자료를 더 압축하는 것만'], '인프라의 확보와 조직의 활용 역량은 다르다. 현업 이해·교육·업무 연결·성과 공유가 부족한지 진단해야 한다.');
q(45,3,'R 요인 수준','factor를 as.numeric으로 직접 변환할 때 주의할 점은?', ['표시된 값 대신 내부 수준 코드가 반환될 수 있다','모든 범주가 자동으로 실제 연속값이 된다','수준 정보가 항상 의미 없는 0이 된다','문자 요인에는 수준이 존재하지 않는다'], 'factor는 수준과 내부 코드를 가진다. 표시된 숫자 모양의 값이 필요하면 적절한 문자 변환 후 수치 변환 등으로 확인해야 한다.');
q(45,3,'R apply','행렬 m에 apply(m,2,mean)을 실행한다. 통상 계산 대상은?', ['각 열의 평균','각 행의 평균','행렬 원소의 중앙값만','행렬의 역행렬'], 'apply의 MARGIN=1은 행, 2는 열 방향이다. 입력 자료형과 반환 구조도 함께 확인한다.');
q(45,3,'평균과 극단값','자료 2,3,4에 100이 추가되었다. 대표값의 성질로 적절한 것은?', ['평균은 극단값의 영향을 크게 받을 수 있다','중앙값은 언제나 평균보다 더 크게 변한다','최빈값은 모든 연속 자료에서 반드시 하나이다','대표값 선택은 자료 분포와 무관하다'], '평균은 모든 값의 크기를 반영하므로 극단값에 민감하다. 중앙값·최빈값 등은 다른 성질을 가지며 자료의 척도·분포·목적에 맞게 선택한다.');
q(45,3,'표본분산 단위','길이를 cm로 측정했다. 분산과 표준편차의 단위는 각각?', ['cm²와 cm','cm와 cm²','둘 다 단위 없음','둘 다 cm'], '분산은 편차 제곱을 이용하므로 cm², 표준편차는 제곱근을 취해 cm다. 표준오차도 평균과 같은 단위를 가진다.');
q(45,3,'베이즈 분모','검사 양성일 때 질환일 확률을 계산하려 한다. 분모에 해당하는 것은?', ['질환·비질환에서 나온 모든 양성의 확률','질환자에게서 나온 양성만','모든 실제 질환자의 확률만','음성 판정의 확률만'], 'P(질환|양성)은 실제 질환의 양성 비율을 전체 양성 비율로 나눈다. 민감도 P(양성|질환)와 조건 방향이 다르다.');
q(45,3,'단측·양측','H₁: μ≠100이라는 대립가설은?', ['양측 검정','오른쪽 단측 검정','왼쪽 단측 검정','모든 차이를 검토하지 않는 검정'], '크거나 작거나 양쪽 방향의 차이를 고려하므로 양측이다. μ>100 또는 μ<100은 각각 단측 대립가설이다.');
q(45,3,'전체 F 검정','다중 선형 회귀의 통상적인 전체 F 검정 귀무가설은?', ['모든 기울기 계수가 0이다','절편이 반드시 1이다','모든 설명변수 관측값이 0이다','각 잔차가 반드시 0이다'], '전체 F 검정은 설명변수들이 절편만 있는 모형보다 설명에 도움이 되는지 본다. 개별 기울기의 t 검정과 검정 대상이 다르다.');
q(45,3,'조정 R²','설명변수를 추가할 때 조정 R²가 일반 R²와 달리 감소할 수 있는 이유는?', ['변수 수에 따른 복잡도 보정을 반영하기 때문','새 변수는 언제나 반응값을 삭제하기 때문','조정 R²는 오직 음수만 가능하기 때문','표본 수를 전혀 사용하지 않기 때문'], '같은 자료의 절편 포함 OLS에서 일반 R²는 변수 추가로 감소하지 않지만 조정 R²는 자유도 보정을 반영한다. 추가 변수가 충분히 도움을 주지 않으면 낮아질 수 있다.');
q(45,3,'과적합','학습 정확도 99%, 검증 정확도 63%다. 먼저 의심할 현상은?', ['과적합 또는 학습·검증 조건의 차이','성능이 모든 자료에서 99%로 보장됨','검증 자료를 버리면 일반화가 개선됨','자료가 적을수록 항상 발생하지 않음'], '학습 자료에만 잘 맞는 패턴은 과적합의 단서다. 자료 분포 차이·누수·평가 조건도 점검하고 새 자료 성능을 기준으로 모형을 조정한다.');
q(45,3,'F1 계산','정밀도 0.8, 재현율 0.8일 때 F1은?', ['0.8','1.6','0.64','0.4'], 'F1=2PR/(P+R)=2×0.8×0.8/1.6=0.8이다. 두 값이 같으면 조화평균도 같은 값이다.');
q(45,3,'완전 연결','계층 군집의 완전 연결은 두 군집 사이 어떤 거리를 사용하는가?', ['점 쌍 거리 중 최댓값','점 쌍 거리 중 최솟값','두 군집의 표본 수 차이만','모든 점의 번호 평균'], '완전 연결은 가장 먼 점 쌍의 거리를 사용한다. 가장 가까운 쌍의 단일 연결, 평균 연결, Ward의 제곱합 증가 기준과 구분한다.');
q(45,3,'Apriori 성질','항목집합 {A,B}가 최소 지지도보다 낮다. Apriori 관점에서 {A,B,C}는?', ['빈발할 수 없다','반드시 빈발하다','신뢰도만으로 빈발이 확정된다','부분집합보다 지지도가 반드시 크다'], '더 큰 항목집합의 출현 거래는 부분집합의 출현 거래를 넘을 수 없다. 비빈발 부분집합을 포함하는 후보는 제외할 수 있다.');

// 46회 보충.
q(46,1,'빅데이터 속도','센서가 계속 보내는 자료를 정해진 짧은 지연 안에 처리해야 한다. 직접 관련된 3V는?', ['Velocity','Variety만','Volume만','Veracity만'], '생성·처리의 속도 요구는 Velocity다. 크기·형식 다양성·신뢰성 문제와 나누어 요구 조건을 정한다.');
q(46,1,'DB 원자성','송금에서 출금은 완료되고 입금이 실패했다. 두 작업을 모두 취소하도록 보장하는 성질은?', ['원자성','지속성만','차원 축소','실루엣'], '하나의 거래를 전체 성공 또는 전체 취소로 처리하는 원자성이다. 확정된 거래의 보존인 지속성과 구분한다.');
q(46,1,'분석 기술의 목적','정답 범주 없이 비슷한 소비 패턴의 고객을 묶는 기법은?', ['군집분석','연속값 회귀','평균의 단일 표본 검정','범주를 정답으로 학습한 분류만'], '정해진 목표 라벨 없이 유사한 대상을 묶는 군집분석이다. 미리 지정된 범주를 예측하는 지도 분류와 다르다.');
q(46,1,'결합 재식별','개별 파일에는 직접 식별자가 없지만 여러 파일을 연결해 개인을 알아냈다. 관련 위험은?', ['결합에 따른 재식별','항상 완전 익명성이 보장됨','데이터 독립성만','표준편차의 감소만'], '직접 식별자를 지워도 준식별자와 다른 자료의 결합으로 식별 가능성이 생길 수 있다. 재식별 위험과 접근·결합 조건을 점검한다.');
q(46,2,'데이터 접근','분석에 필요한 자료가 있지만 권한 승인이 2개월 걸린다. 기획에서 반영할 것은?', ['확보 일정·책임자·대안과 실행 가능성','존재하므로 즉시 사용 가능한 것으로 간주','정확도만 목표로 삼아 일정 무시','승인 전에 모든 사용자에게 자료 공개'], '데이터 존재와 사용 가능성은 다르다. 접근 승인·추출·결합까지의 일정과 책임, 대체 자료나 범위 조정을 검토한다.');
q(46,2,'반복 방법론','평가에서 성능 부족을 확인해 데이터 준비와 변수 구성을 다시 수행한다. 적절한 이해는?', ['분석 방법론의 반복·피드백','이미 지난 단계는 다시 볼 수 없음','최종 평가를 학습 입력으로 넣어야 함','목표를 숨기고 모형만 교체'], '분석 과정은 불확실성을 확인하며 이전 단계로 돌아갈 수 있다. 재작업의 목표와 산출물을 정하고 평가 자료의 역할을 지켜야 한다.');
q(46,2,'우선순위 시급성','전략적 중요성과 필요한 완료 시점을 중심으로 평가하는 관점은?', ['과제의 시급성','거리 척도','분포의 첨도','회귀 잔차의 정규성'], '시급성은 전략·업무 필요 시점 등과 연결된다. 데이터 규모·다양성·처리 요구와 자원의 난이도는 별도 관점이다.');
q(46,2,'운영 모니터링','입력값이 갑자기 모두 0이 되었을 때 가장 먼저 적절한 대응은?', ['수집·변환 오류와 영향 범위를 점검','0으로 즉시 재학습하고 원인은 무시','모든 0을 임의의 양수로 바꿈','성능이 항상 개선되었다고 간주'], '자료 변화는 품질 오류일 수도 있다. 원천과 처리 경로를 확인하고 영향을 파악한 뒤 수정·재평가하며 잘못된 값을 바로 학습하지 않는다.');
q(46,3,'R 정렬 위치','x=c(9,3,6)에서 order(x)의 결과는?', ['2,3,1','3,6,9','3,1,2','1,2,3'], 'order는 정렬된 값이 아니라 원래 위치를 반환한다. 값 3·6·9의 위치는 각각 2·3·1이다.');
q(46,3,'R 조건 분기','여러 점수에 대해 합격·불합격 값을 원소별로 고르려 한다. 적절한 함수는?', ['ifelse','단일 조건 if에 긴 논리 벡터를 그대로 사용','matrix의 역행렬','length만 사용'], 'ifelse는 각 원소 조건에 따라 값을 선택한다. if는 길이 1의 비결측 논리 조건으로 실행 흐름을 분기한다.');
q(46,3,'평균 대체 한계','결측값을 전체 평균으로 일괄 대체했을 때의 주의점은?', ['자료의 산포와 변수 관계를 왜곡할 수 있다','결측 원인이 자동으로 무작위가 된다','모든 추정이 반드시 불편해진다','누락된 실제 값을 정확히 복원한다'], '단순 평균 대체는 변동성을 줄이고 관계를 바꿀 수 있다. 결측 메커니즘과 비율·목적을 확인하고 처리 전후를 평가한다.');
q(46,3,'독립과 배반','확률이 모두 양수인 두 배반 사건에 대한 설명은?', ['하나가 발생하면 다른 사건의 조건부 확률은 0이므로 독립이 아니다','항상 독립이다','교집합은 확률의 합과 같다','합집합 확률은 항상 1이다'], '배반은 교집합 0이다. 두 확률이 양수이면 독립의 교집합 조건 P(A)P(B)>0과 맞지 않는다.');
q(46,3,'공분산에서 상관','공분산 8, 두 표준편차 4와 5일 때 Pearson r은?', ['0.4','2','20','0.8'], 'r=8/(4×5)=0.4다. 공분산을 표준편차의 곱으로 나눠 척도의 영향을 제거한다.');
q(46,3,'유의성과 크기','매우 큰 표본에서 작지만 통계적으로 유의한 차이를 찾았다. 적절한 평가 방식은?', ['효과 크기·신뢰구간·업무 의미도 함께 확인','p가 작으므로 실무 효과도 반드시 크다고 판단','표본 수가 크면 가정은 모두 불필요','귀무가설이 참일 확률로 p를 읽음'], '유의성은 효과의 실무적 크기를 보장하지 않는다. 큰 표본에서는 작은 차이도 유의할 수 있으므로 비용과 효과 크기를 함께 읽는다.');
q(46,3,'로지스틱 오즈','사건 확률 p=0.25의 오즈는?', ['1/3','0.25','3','0.75'], '오즈는 p/(1−p)=0.25/0.75=1/3이다. 확률과 오즈는 다른 척도다.');
q(46,3,'시계열 평가','다음 달 수요 예측 모형의 현실적 평가에 적절한 분할은?', ['과거로 학습하고 이후 기간으로 평가','미래 자료를 과거 입력에 섞어 무작위 분할만','정답 수요를 설명변수로 사용','평가 기간의 평균에 맞춰 학습 자료를 수정'], '예측 시점에 알 수 없는 미래 정보가 학습에 섞이면 누수가 생긴다. 시간 순서와 실제 예측 기간을 반영해 평가한다.');
q(46,3,'Lasso 벌점','Lasso의 대표적인 벌점 형태는?', ['계수 절댓값 합에 비례','계수 제곱합만 사용하는 L2','모든 잔차를 0으로 고정','분류 결과의 번호 합'], 'Lasso는 L1 벌점으로 일부 계수를 0으로 만들 수 있다. Ridge는 L2 제곱합 벌점으로 구분하며 강도는 검증으로 선택한다.');
q(46,3,'양성 기준 변화','양성 기준 임계값을 낮춰 기존보다 많은 사례를 양성으로 예측한다. 통상 확인할 변화는?', ['재현율 증가 가능성과 위양성 증가 가능성','재현율이 반드시 감소','위양성은 절대로 늘지 않음','정밀도는 모든 자료에서 반드시 증가'], '고정된 점수에 낮은 임계값을 적용하면 더 많은 양성을 찾으면서 음성을 잘못 고를 수도 있다. 비용·처리 용량과 실제 지표를 보고 선택한다.');
q(46,3,'PCA 무상관','주성분 사이의 관계에 대한 일반적으로 적절한 설명은?', ['서로 직교한 축의 성분은 무상관이지만 독립은 별도 조건이다','무상관이면 모든 분포에서 항상 독립이다','첫 성분은 반드시 목표값과 최대 상관이다','모든 성분을 줄여도 정보 손실이 없다'], 'PCA의 직교·무상관은 일반적인 독립을 보장하지 않는다. 차원 축소는 일부 정보를 잃을 수 있고 분산 최대화가 목표 예측 최적화와 같지 않다.');
q(46,3,'향상도 기준','연관규칙의 향상도가 정확히 1이다. 해석은?', ['A 조건 아래 B 확률이 B의 기본 확률과 같다','A가 B의 확률을 두 배로 높인다','신뢰도가 반드시 0이다','지지도가 반드시 1이다'], '향상도=P(B|A)/P(B)다. 1이면 이 기준에서 A를 알아도 B의 발생 비율이 변하지 않는다. 다른 지표를 자동으로 0이나 1로 정할 수는 없다.');

// 47회 보충.
q(47,1,'DIKW 규칙 이해','여러 주의 기록으로 행사와 방문객 증가의 관계를 이해했다. DIKW에서 가까운 단계는?', ['지식','가공 전 데이터','파일 자료형','조건 없는 지혜'], '관계나 규칙을 이해한 단계는 지식이다. 그 이해를 바탕으로 행동을 판단하는 것은 지혜이며 관계 이해가 인과 입증을 자동 보장하지 않는다.');
q(47,1,'DB 일관성','같은 고객 주소가 두 업무 파일에서 서로 다르다. 직접적인 문제는?', ['중복 관리 실패에 따른 데이터 불일치','분류 임계값의 상승','표본 크기의 증가','성공적인 참조 무결성의 증명'], '중복 저장한 같은 사실을 일부만 갱신하면 값이 달라질 수 있다. 통합 기준과 갱신 절차·키를 관리해야 한다.');
q(47,1,'데이터 과학의 설명','좋은 예측 결과를 전달할 때 반드시 함께 설명할 내용은?', ['가정·자료 범위·한계·사용 조건','정확도 숫자만','알고리즘 이름의 길이만','가장 유리한 결과만'], '결과를 어디에 어떻게 사용할 수 있는지 판단하도록 근거·불확실성·적용 조건을 설명한다. 높은 점수만으로 모든 업무에 적용할 수는 없다.');
q(47,1,'로그 대표성','앱 이용자의 모든 로그를 모았다. 전체 국민의 행동을 대표한다고 바로 할 수 없는 이유는?', ['앱을 쓰지 않는 대상이 수집 과정에서 빠질 수 있기 때문','모든 로그는 확률 표본이기 때문','전수라는 표현만으로 편향이 사라지기 때문','양이 많으면 모집단 정의가 불필요하기 때문'], '기록된 자료의 전체와 관심 모집단의 전체는 다를 수 있다. 자료 수집 경로와 제외된 대상을 확인해야 대표성을 판단할 수 있다.');
q(47,2,'분석 난이도','많은 자료량·여러 형식·빠른 처리 요구로 실행이 어려운 과제다. 관련 판단은?', ['3V 관점의 분석 난이도','업무 시급성이 자동으로 낮음','기대 가치가 반드시 0','데이터와 무관한 표지 디자인'], 'Volume·Variety·Velocity는 처리 규모·다양성·속도의 난이도와 연결된다. 기대 가치와 시급성은 별도로 판단해야 한다.');
q(47,2,'중단 없는 반복','반복 개발에서도 정해야 할 관리 항목은?', ['각 반복의 목표·산출물·완료 기준','최종 목표의 영구 삭제','검증 자료의 자유로운 학습 사용','소통 기록의 금지'], '반복은 불확실성에 대응하는 방식이며 기준 없는 탐색을 뜻하지 않는다. 검증 목표와 완료 조건을 정하고 결과로 계획을 갱신한다.');
q(47,2,'운영 결과 평가','예측 점수를 사용한 뒤 실제 손실 감소를 확인한다. 이는?', ['업무 성과 평가','학습 자료의 행 정렬만','표본분산을 무조건 0으로 만드는 것','변수 자료형 변경만'], '모형의 기술 성능과 실제 업무 효과는 다르다. 기준선·기간·대상·실행률·비용을 포함해 활용 성과를 평가해야 한다.');
q(47,2,'마스터 데이터','여러 부서가 공통으로 사용하는 고객·상품의 기준 기록은?', ['마스터 데이터','오차항만','임시 그래프의 색상','모든 자료의 파일 크기'], '고객·상품 등의 공통 기준 자료는 마스터 데이터다. 그 자료의 의미·구조·갱신 규칙을 설명하는 메타데이터와 구분한다.');
q(47,3,'R 그룹 평균','값 2,6,10,14의 그룹이 A,A,B,B다. 그룹별 평균은?', ['A=4, B=12','A=8, B=8','A=2, B=10','A=6, B=14'], 'A의 평균은 (2+6)/2=4, B는 (10+14)/2=12다. tapply나 aggregate 등으로 그룹·변수·함수를 지정할 수 있다.');
q(47,3,'R NULL과 NA','R에서 NULL과 NA의 구분으로 적절한 것은?', ['NULL은 객체의 부재, NA는 결측값을 표현한다','둘은 모든 자료 구조에서 완전히 같은 값이다','NA는 무조건 문자 하나이다','NULL은 모든 벡터에서 길이 1 결측이다'], 'NULL과 NA는 서로 다른 개념이다. 결측 원소와 객체의 부재를 혼동하면 길이·추출·조건 계산을 잘못 읽을 수 있다.');
q(47,3,'중앙값과 순서','값 8,1,6,3,9의 중앙값은?', ['6','8','5.4','3'], '정렬하면 1·3·6·8·9이며 가운데 값은 6이다. 원래 나열의 가운데 값이 우연히 같을 수 있지만 중앙값의 정의는 정렬된 위치다.');
q(47,3,'조건부 확률','전체 80명 중 A가 20명, A와 B 모두인 사람이 12명이다. P(B|A)는?', ['0.6','0.15','0.25','0.4'], '조건 A의 20명을 분모로 두면 12/20=0.6이다. 전체 80명을 분모로 쓰면 결합확률 0.15를 계산한다.');
q(47,3,'신뢰수준과 폭','동일 자료에서 평균 신뢰수준을 95%에서 99%로 높인다. 통상 구간 폭은?', ['넓어진다','좁아진다','항상 같다','반드시 길이 0이 된다'], '더 높은 포함률을 확보하려면 더 큰 임계값을 사용해 구간이 넓어진다. 표본 수·표준편차 등 다른 조건이 같다는 전제다.');
q(47,3,'검정 p값','p값 0.02의 해석으로 올바른 것은?', ['귀무가설과 가정 아래 관측만큼 또는 더 극단적 결과의 확률','귀무가설이 참일 확률 2%','대립가설이 참일 확률 98%','결과가 실무적으로 클 확률 98%'], 'p값은 가정 아래의 자료·통계량 확률이다. 가설 자체의 확률이나 업무 효과의 크기로 바꿔 읽지 않는다.');
q(47,3,'잔차 제곱합','잔차가 −1,2,−2인 모형의 잔차 제곱합은?', ['9','3','5','√9'], '각 제곱은 1·4·4이며 합은 9이다. 평균 제곱오차는 정의에 따라 이를 관측 수로 나누는 별도 계산이다.');
q(47,3,'단순 지수평활','이전 평활값 50, 새 관측 70, α=0.2이다. 새 평활값은?', ['54','64','60','14'], '0.2×70+0.8×50=14+40=54다. 새 값의 반영률 α가 작으면 이전 요약의 비중이 더 크다.');
q(47,3,'OOB 표본','A,B,C,D에서 복원 추출 결과 A,C,C,D가 나왔다. 이 표본의 OOB 기록은?', ['B','C','A와 D','전체 기록'], '뽑히지 않은 B가 이 부트스트랩 표본의 OOB다. 다른 나무의 추출에서는 OOB 기록이 달라질 수 있다.');
q(47,3,'코사인 유사도','두 0이 아닌 벡터의 코사인 유사도가 1이다. 의미는?', ['같은 방향이다','길이가 반드시 같다','모든 좌표 값이 반드시 같다','유클리드 거리가 반드시 0이다'], '코사인은 방향의 유사도를 본다. 양의 배수 관계라면 크기가 달라도 1일 수 있으므로 거리 0과 같은 뜻이 아니다.');
q(47,3,'실루엣 계산','군집 내 평균 거리 a=3, 가장 가까운 다른 군집 평균 거리 b=6이다. 실루엣은?', ['0.5','1','−0.5','3'], 's=(b−a)/max(a,b)=(6−3)/6=0.5다. 같은 군집의 거리가 작고 다른 군집의 거리가 클수록 좋은 방향의 지표다.');
q(47,3,'규칙의 해석','동시 구매 규칙 A→B의 신뢰도가 높다. 바로 단정할 수 없는 것은?', ['A 구매가 B 구매의 원인이라는 결론','A 거래 중 B 동시 거래의 비율','조건 방향에 따라 분모가 달라지는 점','B 기본 비율을 향상도에서 고려하는 점'], '연관규칙은 함께 나타나는 패턴이지 인과나 구매 시간 순서를 입증하지 않는다. 신뢰도와 향상도 등 지표의 의미를 구분해 활용한다.');

// 48회: 기존 주제 35문제 + 학습 범위 보충 15문제.
q(48,1,'DIKW 단계','매장별 주문 기록을 정리해 금요일 저녁에 주문이 반복 증가한다는 패턴을 이해했다. DIKW에서 이 패턴의 이해는?', ['지식','아직 정리하지 않은 데이터','단순 주문 건수만인 데이터','모든 경우에 적용되는 절대적 지혜'], '정보에서 의미 있는 패턴을 파악하고 맥락을 이해하는 단계는 지식이다. 그 이해를 토대로 인력 배치 같은 판단을 내리는 단계와 구분한다.');
q(48,1,'지식 변환','숙련자가 머릿속 판단 기준을 작업 지침서로 정리했다. SECI의 어떤 과정인가?', ['표출화','사회화','내면화','결합화만'], '암묵지를 말·문서 등 형식지로 표현하는 과정은 표출화다. 형식지를 실행하며 자신의 경험으로 익히는 내면화와 방향이 반대다.');
q(48,1,'데이터 독립성','저장 파일의 물리적 배치가 바뀌어도 사용자의 논리적 조회 방식은 유지되도록 설계했다. 관련 개념은?', ['물리적 데이터 독립성','모든 데이터의 완전 공개','같은 값의 무제한 복제','트랜잭션의 영구 중단'], '물리적 저장 구조의 변화가 상위 논리 구조에 미치는 영향을 줄이는 개념이다. 논리적 구조 변화와 외부 관점의 관계를 다루는 논리적 독립성과 구분한다.');
q(48,2,'범위 변경 관리','분석 중 고객이 새로운 대상을 추가했다. 계획에서 우선 검토할 것은?', ['일정·비용·데이터·검증 기준에 미치는 영향','기존 완료 기준을 그대로 둔 채 무조건 추가','검증 단계의 생략','모든 책임자의 삭제'], '대상 변경은 자료 확보·업무 범위·산출물·성공 기준에 영향을 준다. 변경 영향을 파악하고 관계자와 범위·일정을 조정해야 한다.');
q(48,3,'R 논리 인덱스','x <- c(4,9,2,11)일 때 x[x > 5]의 결과는?', ['9, 11','4, 2','TRUE, FALSE','5, 5'], 'x > 5는 FALSE·TRUE·FALSE·TRUE이며 TRUE 위치의 값을 추출한다. 비교의 결과 자체와 비교를 인덱스로 사용한 추출 결과를 구분한다.');
q(48,3,'R 결측 계산','x <- c(3, NA, 9)에서 mean(x, na.rm=TRUE)의 결과는?', ['6','NA','4','12'], '결측을 제외하고 남은 3과 9의 평균을 계산해 6이다. 결측을 0으로 대체하는 동작과 같지 않다.');
q(48,3,'분산 계산','값 2,4,6의 표본분산은?', ['4','8/3','2','8'], '평균은 4, 편차제곱합은 4+0+4=8이다. 표본분산은 n−1=2로 나누어 4이며, 표준편차는 2다.');
q(48,3,'베이즈 해석','양성 검사 결과의 실제 질환 확률을 판단할 때 필요한 정보는?', ['유병률과 민감도·특이도 등 검사 성능','민감도 하나만','검사 이름의 길이만','표본의 정렬 순서만'], '검사 양성 중 실제 질환인 비율은 질환의 사전 확률과 위양성 발생률에도 영향을 받는다. 민감도와 양성예측도를 같은 값으로 읽지 않는다.');
q(48,3,'표준오차','같은 표준편차에서 표본 크기를 25에서 100으로 늘렸다. 표본평균의 표준오차는?', ['기존의 1/2','기존의 1/4','기존의 2배','기존과 동일'], '평균의 표준오차는 σ/√n이다. √25=5에서 √100=10으로 분모가 두 배가 되어 표준오차는 절반이 된다.');
q(48,3,'다중 검정','20개 가설을 각각 5% 유의수준으로 검정했다. 우선 주의할 내용은?', ['하나 이상 제1종 오류를 낼 위험이 커질 수 있음','전체 오류 확률이 반드시 5%라는 보장','모든 p값이 자동으로 20분의 1로 감소','모든 가설이 반드시 참'], '개별 검정의 유의수준과 여러 검정 전체의 오류 통제는 다르다. 목적에 맞게 다중비교 보정이나 오류율 통제를 고려한다.');
q(48,3,'회귀 예측','ŷ=5+3x인 모형에서 x=4의 예측값은?', ['17','12','20','8'], '절편 5와 기울기 3을 대입해 5+3×4=17이다. 모형의 적용 범위 밖 외삽에는 별도의 주의가 필요하다.');
q(48,3,'규제 효과','변수 척도를 고려한 릿지 회귀의 일반적인 효과는?', ['계수 크기를 줄여 분산과 과적합을 완화할 수 있음','모든 계수를 반드시 정확히 0으로 만듦','시험 자료를 학습에 넣음','오차를 항상 0으로 보장'], '릿지는 L2 벌점을 사용한다. 계수를 수축시키지만 일반적으로 변수 선택을 위해 정확한 0을 만드는 라쏘와 구분한다.');
q(48,3,'부트스트랩','크기 n인 원표본에서 크기 n으로 복원 추출한다. 가능한 현상은?', ['일부 기록은 중복되고 일부는 뽑히지 않음','모든 기록이 정확히 한 번씩만 선택','선택된 값은 반드시 원자료에 없음','모든 재표본이 반드시 동일'], '복원 추출은 같은 기록의 반복 선택을 허용한다. 뽑히지 않은 기록이 생길 수 있고, 재표본 간 통계량의 변동을 살펴볼 수 있다.');
q(48,3,'군집 표준화','키(cm)와 연소득(원)을 원래 단위 그대로 유클리드 거리로 비교한다. 주의할 점은?', ['수치 규모가 큰 변수의 영향이 지배적일 수 있음','단위는 거리에 절대 영향을 주지 않음','모든 군집이 자동으로 한 개가 됨','항상 같은 분산을 가짐'], '거리 계산은 척도의 영향을 받는다. 분석 목적과 변수 의미를 고려해 표준화나 적절한 거리 척도를 검토한다.');
q(48,3,'연관규칙 계산','200건에서 A 50건, B 80건, 동시 A·B 30건이다. A→B 향상도는?', ['1.5','0.6','0.15','2.5'], '신뢰도는 30/50=0.6, B의 기본 비율은 80/200=0.4다. 향상도는 0.6/0.4=1.5이며 지지도는 0.15다.');

// 49회: 기존 주제 35문제 + 학습 범위 보충 15문제.
q(49,1,'DIKW 적용','이탈이 반복되는 조건을 이해한 뒤 고객 유지 정책을 선택했다. DIKW에서 정책 선택에 가장 가까운 단계는?', ['지혜','가공 전 데이터','단순 정보','저장 매체'], '지식과 맥락을 이용해 적절한 행동을 판단하는 단계가 지혜다. 정책의 실제 효과는 실행 후 검증해야 한다.');
q(49,1,'정형 데이터','정해진 열과 자료형으로 관리하는 매출 관계형 테이블은 주로 어떤 데이터인가?', ['정형 데이터','모든 경우 비정형 데이터','구조가 없는 음성 파일만','메타데이터만 존재하는 데이터'], '정형 데이터는 사전에 정한 스키마에 맞춰 관리된다. JSON·XML 같은 자체 구조의 반정형 자료, 자유 텍스트·이미지 같은 비정형 자료와 구분한다.');
q(49,1,'ACID 격리성','동시에 실행되는 트랜잭션이 서로의 미완료 작업에 부적절하게 영향을 주지 않도록 한다. 관련 특성은?', ['격리성','원자성만','지속성만','파일 크기'], '격리성은 동시 실행의 상호 영향을 관리하는 성질이다. 실제 허용 현상은 격리 수준에 따라 달라지므로 모든 수준을 완전 직렬화와 같다고 읽지 않는다.');
q(49,1,'데이터 품질','주소 값이 허용된 형식에 맞는지와 실제 거주지를 정확히 나타내는지를 구분했다. 적절한 판단은?', ['형식 유효성과 실제 정확성은 별도로 확인','형식에 맞으면 실제 값도 반드시 정확','주소가 길면 항상 완전','모든 공란이 항상 오류'], '형식·범위 검사를 통과한 값도 현실을 잘못 나타낼 수 있다. 품질 차원을 구분하고 데이터의 사용 목적에 맞게 평가한다.');
q(49,1,'대표성과 규모','편향된 수집 경로를 그대로 두고 기록 수만 크게 늘렸다. 적절한 설명은?', ['규모 확대만으로 선택 편향이 사라지지는 않음','큰 데이터면 항상 전체 모집단을 대표','표본 수 증가가 인과관계를 입증','자료형이 자동으로 비율척도로 바뀜'], '규모는 무작위 오차를 줄이는 데 도움이 될 수 있지만, 누락 대상이나 선택 과정에서 생긴 체계적 편향을 자동 해결하지는 않는다.');
q(49,2,'발견형 접근','명확한 문제 정의가 어려워 먼저 자료에서 새로운 패턴을 찾고 업무 과제를 제안했다. 적절한 접근은?', ['상향식 탐색','문제와 해법을 사전에 모두 확정하는 방식만','모든 분석 없이 실행','표본을 무조건 삭제하는 방식'], '상향식은 자료를 탐색하며 새로운 통찰과 과제를 발견하는 접근이다. 발견한 패턴이 실무 가치가 있는지 업무 맥락과 검증으로 연결한다.');
q(49,2,'분석 과제 우선순위','구현이 쉬운 과제라는 이유만으로 가장 먼저 실행하기 전에 함께 볼 항목은?', ['사업 가치·시급성·실행 가능성·의존 관계','화면 제목의 길이만','분석가의 선호 도구만','모든 과제의 동일한 순위'], '난이도뿐 아니라 가치·시급성·자원·선행 조건을 함께 평가한다. 쉬운 과제라도 업무 효과가 없거나 선행 자료가 부족하면 우선순위가 달라질 수 있다.');
q(49,3,'R 데이터 프레임','행 4개, 열 3개인 데이터 프레임 df에서 nrow(df), ncol(df)는?', ['4, 3','3, 4','12, 1','7, 7'], 'nrow는 행 수, ncol은 열 수다. length(df)는 데이터 프레임을 이루는 열의 개수를 반환하므로 전체 셀 수와 구분한다.');
q(49,3,'표준점수 해석','평균 60, 표준편차 8인 집단에서 값 76의 z점수는?', ['2','16','0.5','9.5'], 'z=(76−60)/8=2다. 평균보다 표준편차 두 배만큼 위에 있다는 상대적 위치이며 정규성 자체를 입증하지는 않는다.');
q(49,3,'대응 표본','같은 사람 18명의 운동 프로그램 전후 혈압을 비교한다. 비교 구조는?', ['대응 표본','서로 무관한 두 집단만','명목형 빈도표만','군집 중심만'], '동일 대상의 전후 값은 짝이 있다. 차이값의 분포와 가정을 확인해 대응 t검정 또는 적절한 대안을 선택한다.');
q(49,3,'검정력','실제로 거짓인 귀무가설을 올바르게 기각할 확률은?', ['1−β','α','β','1−α만'], '검정력은 제2종 오류 확률 β의 보완인 1−β다. 효과 크기·표본 수·변동·유의수준 등에 영향을 받는다.');
q(49,3,'회귀 결정계수','절편이 있는 같은 자료의 선형회귀에서 R²=0.72다. 적절한 해석은?', ['반응변수의 관측 변동 중 72%를 모형이 설명','모든 미래 예측이 72% 정확','모든 계수가 유의할 확률 72%','인과관계 확률 72%'], '일반적인 절편 포함 회귀의 R²는 전체 제곱합 대비 설명한 변동 비율이다. 예측의 일반화나 개별 계수의 유의성·인과를 같은 숫자로 판단하지 않는다.');
q(49,3,'분류 임계값','다른 조건이 같을 때 양성 판정 임계값을 높인다. 일반적인 변화는?', ['양성 예측이 줄고 재현율이 낮아질 수 있음','양성 예측이 반드시 늘어남','위양성이 반드시 증가','실제 양성 수가 바뀜'], '임계값을 높이면 양성으로 선택하는 대상이 줄어든다. 실제 클래스 수는 바뀌지 않으며, 오탐·미탐 비용을 고려해 임계값을 정한다.');
q(49,3,'교차검증 전처리','교차검증에서 표준화 평균과 표준편차를 계산할 바람직한 위치는?', ['각 학습 폴드 안','검증 폴드를 포함한 전체 자료에서 항상 먼저','최종 시험 자료에서만','정답 레이블로 임의 결정'], '전처리도 학습 과정의 일부다. 각 학습 폴드에서 변환을 학습하고 검증 폴드에는 그 변환을 적용해야 정보 누출을 줄일 수 있다.');
q(49,3,'최소 지지도','전체 거래 250건, 최소 지지도 8%다. 빈발 항목집합이 되려면 최소 몇 건에 나타나야 하는가?', ['20건','8건','31건','250건'], '250×0.08=20건이다. 최소 지지도는 전체 거래에 대한 출현 비율이며 신뢰도의 조건부 분모와 구분한다.');

// 50회: 기존 주제 30문제 + 학습 범위 보충 20문제.
q(50,2,'분석 목표 구체화','고객 이탈을 줄이려는 분석 과제의 목표를 구체화한 설명은?', ['대상·기간·이탈 정의·활용 방법·성과 기준을 정함','정확도라는 단어만 정함','데이터를 많이 저장하면 완료','도구 설치 자체를 업무 성과로 확정'], '목표를 측정 가능하게 정의하고 결과를 어떻게 실행할지 연결해야 한다. 예측 성능과 실제 이탈 감소의 업무 성과를 구분한다.');
q(50,2,'데이터 확보성','좋은 분석 아이디어가 있지만 필수 기록에 접근할 수 없다. 계획 단계의 적절한 대응은?', ['확보·대체·수집 가능성과 일정 영향을 검토','이미 확보했다고 가정해 최종 결론 작성','검증 없이 임의 값을 실제 값으로 표시','모든 품질 확인 생략'], '가용 데이터·권한·수집 기간·비용을 확인해야 실행 가능한 계획이 된다. 부족한 기록을 허구의 실제 자료로 바꾸어 사용할 수는 없다.');
q(50,2,'평가와 전개','CRISP-DM에서 평가 단계의 핵심 질문은?', ['분석 결과가 업무 목표와 활용 조건을 만족하는가','모든 모형이 반드시 100% 정확한가','사용자 요구를 처음으로 영구 삭제할 것인가','파일을 정렬했으므로 바로 종료할 것인가'], '평가는 기술 성능뿐 아니라 업무 목표·제약·누락된 과정 등을 확인하는 단계다. 전개는 결과의 실제 적용·운영·모니터링으로 연결된다.');
q(50,2,'분석 조직 협업','중앙 분석팀과 각 부서 담당자가 함께 과제를 수행한다. 우선 명확히 할 내용은?', ['역할·의사결정 권한·요청 및 공유 절차','모든 담당자의 역할을 동일하게만 둠','현업 요구의 전달 금지','오류 책임의 무조건 회피'], '조직의 배치 형태만으로 협업이 완성되지는 않는다. 요청·우선순위·데이터 책임·배포·운영의 역할과 소통 경로를 정한다.');
q(50,2,'단계별 로드맵','데이터 품질과 운영 역량이 부족한 조직의 적절한 분석 로드맵은?', ['기초 관리와 작은 검증 과제를 마련하고 점진적으로 확장','가장 복잡한 모델을 무조건 전사 배포','성공 기준 없는 프로젝트를 동시에 무제한 시작','기반 데이터 정비를 영구 생략'], '준비 수준·선행 조건을 고려해 역량과 활용 범위를 단계적으로 늘린다. 작은 성과를 평가하되 단기 모델 점수만으로 성숙도를 단정하지 않는다.');
q(50,2,'성과 지표 관리','같은 성과 지표의 부서별 계산값이 다르다. 우선 관리할 항목은?', ['정의·분모·기간·집계 규칙·책임자','화면 색만','가장 큰 값을 무조건 정답으로 선택','자료를 보지 않고 평균으로 합침'], '지표 표준을 정하고 데이터 흐름과 갱신 기준을 공유해야 비교가 가능하다. 이름이 같은 지표라도 계산 범위가 다르면 서로 다른 값을 낼 수 있다.');
q(50,3,'R 정렬 인덱스','x <- c(7,2,5)일 때 order(x)의 결과는?', ['2, 3, 1','2, 5, 7','1, 2, 3','7, 5, 2'], 'order는 정렬된 값이 아니라 그 순서를 만드는 원래 위치를 반환한다. x[order(x)]를 계산하면 값 2·5·7을 얻는다.');
q(50,3,'R 순환 규칙','c(1,2,3,4) + c(10,20)의 결과는?', ['11, 22, 13, 24','11, 22만','10, 40, 30, 80','모든 경우 길이 오류'], '짧은 벡터 10·20이 반복되어 10·20·10·20으로 대응된다. 긴 벡터의 길이가 짧은 길이의 배수인 예시이며 행렬곱과 구분한다.');
q(50,3,'확률의 합','P(A)=0.4, P(B)=0.5, P(A∩B)=0.2다. P(A∪B)는?', ['0.7','0.9','0.2','1.1'], '합집합은 0.4+0.5−0.2=0.7이다. 공통 부분을 두 번 더하지 않도록 한 번 빼며 독립을 가정할 필요는 없다.');
q(50,3,'정규분포','정규분포의 평균 μ와 표준편차 σ의 역할을 올바르게 연결한 것은?', ['μ는 중심, σ는 퍼짐','μ는 퍼짐, σ는 범주 수','σ는 언제나 1로 고정','μ가 크면 분산은 반드시 0'], '평균은 분포의 위치, 표준편차는 흩어진 정도를 나타낸다. 표준정규분포에서는 μ=0, σ=1이며 모든 정규분포가 처음부터 표준정규인 것은 아니다.');
q(50,3,'신뢰구간 계산','평균 30, 알려진 σ=10, n=100이다. 정규 근사 95% 평균 신뢰구간은?', ['28.04~31.96','10.4~49.6','29.95~30.05','20~40'], '표준오차는 10/√100=1, 오차 한계는 1.96이다. 30±1.96으로 28.04~31.96을 얻는다.');
q(50,3,'ANOVA 사후 비교','세 집단 일원분산분석에서 귀무가설을 기각했다. 다음 해석으로 적절한 것은?', ['적어도 한 평균이 다르며 어느 쌍인지 추가 비교가 필요','모든 쌍의 평균이 반드시 다름','모든 집단 분산이 반드시 다름','평균이 같은 것이 입증됨'], '전체 F검정은 적어도 한 집단 평균 차이를 판단한다. 어떤 집단 쌍이 다른지는 다중비교를 고려한 사후 분석으로 살펴본다.');
q(50,3,'잔차 진단','잔차 대 예측값 그래프가 오른쪽으로 갈수록 부채꼴로 넓어진다. 의심할 가정은?', ['등분산성','변수 이름의 유일성','종속변수의 명목척도','모든 계수가 정확히 0이라는 가정'], '예측값 수준에 따라 오차의 변동이 달라지는 이분산 가능성이 있다. 잔차 구조를 확인하고 목적에 맞는 변환·추정·추론 대안을 검토한다.');
q(50,3,'다중공선성 해석','VIF가 큰 설명변수를 확인했다. 적절한 후속 검토는?', ['변수 간 선형 중복과 계수 추정 불안정성','해당 변수가 반드시 종속변수의 원인','모형의 미래 성능이 반드시 최고','모든 잔차의 독립성이 입증'], 'VIF는 설명변수 간 선형 관계 때문에 계수 분산이 얼마나 커지는지를 보는 지표다. 인과나 잔차 독립성 검정으로 바꿔 해석하지 않는다.');
q(50,3,'로지스틱 오즈','사건 확률 p=0.8일 때 오즈 p/(1−p)는?', ['4','0.8','0.2','1.25'], '0.8/0.2=4다. 확률은 0~1 사이지만 오즈는 1을 넘을 수 있으며 로그오즈는 또 다른 척도다.');
q(50,3,'분류 정밀도','TP=18, FP=6, FN=12일 때 정밀도는?', ['75%','60%','50%','90%'], '정밀도는 양성이라고 예측한 TP+FP를 분모로 하여 18/24=75%다. 재현율은 실제 양성 TP+FN을 분모로 하여 60%다.');
q(50,3,'과적합 진단','학습 오차는 계속 감소하지만 검증 오차는 다시 증가했다. 가장 관련 있는 현상은?', ['과적합','검증 성능의 무조건 개선','자료 누출이 절대 없다는 입증','편향과 분산이 동시에 반드시 0'], '학습 자료의 세부 잡음까지 맞추며 새 자료에 대한 일반화가 나빠질 수 있다. 복잡도·규제·학습 종료 등을 검증 성능으로 조절한다.');
q(50,3,'시계열 차분','관측값이 5,9,12,18이다. 1차 차분은?', ['4, 3, 6','5, 9, 12','14, 21, 30','−4, −3, −6'], '각 값에서 직전 값을 빼면 9−5=4, 12−9=3, 18−12=6이다. 1차 차분은 추세 제거에 쓰일 수 있지만 정상성을 자동 보장하지 않는다.');
q(50,3,'K-means 중심','한 군집의 1차원 값이 2,5,8이다. K-means 갱신 중심은?', ['5','2','8','15'], '중심은 배정된 관측의 평균이며 (2+5+8)/3=5다. 초기화·거리·척도에 따라 군집 결과가 달라질 수 있다.');
q(50,3,'향상도 기준','연관규칙의 향상도가 1이다. 관련 해석은?', ['동시 출현이 독립 기준의 기대 수준과 같음','A가 B의 원인임을 입증','A와 B가 절대 함께 안 나타남','신뢰도가 반드시 100%'], '향상도는 P(B|A)/P(B)로 독립 기준 대비 관계를 본다. 1은 그 기준의 기대 수준이며 신뢰도 자체의 값이나 인과를 뜻하지 않는다.');

const counters = {};
export const ROUND_SUPPLEMENTS = rows.map((row) => {
  const index = counters[row.round] = (counters[row.round] ?? 0) + 1;
  const shift = (row.round + index * 3) % 4;
  return {
    ...row,
    id: `r${row.round}-extra-${String(index).padStart(3, '0')}`,
    options: row.options.slice(shift).concat(row.options.slice(0, shift)),
    answer: (4 - shift) % 4,
    source: 'syllabus',
    supplement: true,
    kind: '출제 범위 기반 보충',
  };
});
